import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Alert from 'flarum/common/components/Alert';
export default class LSCacheSupportTest extends Component {
  oninit(vnode) {
    super.oninit(vnode);
    if (app.cache.lsCacheDiagnoseData) return;
    app.request({
      url: "".concat(app.forum.attribute('apiUrl'), "/lscache-diagnose")
    }).then(data => {
      app.cache.lsCacheDiagnoseData = data;
      m.redraw();
    });
  }
  view(vnode) {
    const diagnoseData = app.cache.lsCacheDiagnoseData;
    if (!diagnoseData || diagnoseData.cacheSupported) {
      return null;
    }
    const serverSoftware = diagnoseData.serverSoftware,
      litespeedServerType = diagnoseData.litespeedServerType;
    return m(Alert, {
      type: "error",
      dismissible: false
    }, app.translator.trans('acpl-lscache.admin.test_failed_alert', {
      b: m("b", null),
      server: serverSoftware,
      type: litespeedServerType
    }));
  }
}
flarum.reg.add('acpl-lscache', 'admin/components/LSCacheSupportTest', LSCacheSupportTest);